function fakeSdk(options: { persistedExtensions?: boolean } = {}) {
  let config: SessionConfig | undefined;
  const configure = (created: SessionConfig) => {
    if (options.persistedExtensions && created.requestExtensions !== false)
      throw new Error(
        "Failed to initialize standalone session extensions: extensionSdkPath is required when standalone extensions are requested",
      );
    config = created;
  };
  let serial = 0;
  let disconnected = 0;
  let stopped = 0;
  let resumed: string | undefined;
  let conflict = false;
  let continuePendingWork: boolean | undefined;
  const permissionReplies: Array<
    Parameters<CopilotSession["rpc"]["permissions"]["handlePendingPermissionRequest"]>[0]
  > = [];
  let permissionResponse = async (): Promise<{ success: boolean }> => ({ success: true });
  let background: Awaited<ReturnType<SessionHandle["rpc"]["tasks"]["list"]>> = { tasks: [] };
  let taskFailure: Error | undefined;
  let skills: Awaited<ReturnType<SessionHandle["rpc"]["skills"]["list"]>> = { skills: [] };
  let readSkills: (() => Promise<typeof skills>) | undefined;
  let skillFailure: Error | undefined;
  let catalog: ModelCatalog = { models: [] };
  let current: Awaited<ReturnType<SessionHandle["rpc"]["model"]["getCurrent"]>> = {
    modelId: "gpt-4.1",
  };
  const modelChanges: Array<{ model: string; options: Parameters<SessionHandle["setModel"]>[1] }> =
    [];
  const sent: MessageOptions[] = [];
  const emit = (
    type: SessionEvent["type"],
    data: unknown = {},
    agentId?: string,
    timestamp = "2026-10-29T00:00:00Z",
  ) => {
    config?.onEvent?.({
      type,
      data,
      id: `native-event-${++serial}`,
      timestamp,
      parentId: null,
      ...(agentId ? { agentId } : {}),
    } as SessionEvent);
  };
  const session: SessionHandle = {
    sessionId: "native-copilot",
    send: async (message) => {
      sent.push(typeof message === "string" ? { prompt: message } : message);
      return `native-user-message-${sent.length}`;
    },
    abort: async () => {
      emit("session.idle");
    },
    disconnect: async () => {
      disconnected++;
    },
    getEvents: async () => [],
    setModel: async (model, options) => {
      modelChanges.push({ model, options });
    },
    rpc: {
      model: {
        list: async () => ({ list: [], ...(catalog.auto ? { auto: catalog.auto } : {}) }),
        getCurrent: async () => current,
      },
      mode: { set: async () => ({ status: "success", modelChanged: false, modeApplied: true }) },
      plan: {
        read: async () => ({
          exists: true,
          content: "# Plan\n\nImplement safely",
          path: "/copilot/plan.md",
        }),
      },
      skills: {
        list: () => readSkills?.() ?? Promise.resolve(skills),
        enable: async ({ name }) => {
          if (skillFailure) throw skillFailure;
          skills = {
            skills: skills.skills.map((skill) =>
              skill.name === name ? { ...skill, enabled: true } : skill,
            ),
          };
        },
        disable: async ({ name }) => {
          if (skillFailure) throw skillFailure;
          skills = {
            skills: skills.skills.map((skill) =>
              skill.name === name ? { ...skill, enabled: false } : skill,
            ),
          };
        },
      },
      tasks: {
        list: async () => {
          if (taskFailure) throw taskFailure;
          return background;
        },
        cancel: async () => ({ cancelled: true }),
      },
      permissions: {
        handlePendingPermissionRequest: async (
          response: Parameters<
            CopilotSession["rpc"]["permissions"]["handlePendingPermissionRequest"]
          >[0],
        ) => {
          permissionReplies.push(response);
          return permissionResponse();
        },
      },
    },
  };
  const client: ClientHandle = {
    rpc: { models: { list: async () => catalog } },
    start: async () => {},
    stop: async () => {
      stopped++;
      return [];
    },
    forceStop: async () => {},
    createSession: async (created) => {
      configure(created);
      emit("session.idle");
      return session;
    },
    resumeSession: async (id, created) => {
      resumed = id;
      continuePendingWork = created.continuePendingWork;
      configure(created);
      emit("session.resume", { alreadyInUse: conflict });
      return session;
    },
  };
  return {
    client,
    session,
    sent,
    emit,
    modelChanges,
    setCatalog: (value: ModelCatalog) => {
      catalog = value;
    },
    setCurrent: (value: typeof current) => {
      current = value;
    },
    get config() {
      return config!;
    },
    get resumed() {
      return resumed;
    },
    get continuePendingWork() {
      return continuePendingWork;
    },
    get disconnected() {
      return disconnected;
    },
    get stopped() {
      return stopped;
    },
    conflict: () => {
      conflict = true;
    },
    setTasks: (tasks: typeof background) => {
      background = tasks;
    },
    failTasks: (error?: Error) => {
      taskFailure = error;
    },
    setSkills: (value: typeof skills) => {
      skills = value;
    },
    setSkillsRead: (read: typeof readSkills) => {
      readSkills = read;
    },
    get skills() {
      return skills.skills;
    },
    setSkillFailure: (value: Error | undefined) => {
      skillFailure = value;
    },
    permissionReplies,
    setPermissionResponse: (response: () => Promise<{ success: boolean }>) => {
      permissionResponse = response;
    },
  };
}
type Fake = ReturnType<typeof fakeSdk>;
const durablePhase = (phaseId: string): SessionEvent => ({
  type: "assistant.fusion_phase_completed",
  id: `durable-${phaseId}`,
  timestamp: "2026-10-29T00:00:02Z",
  parentId: null,
  data: {
    fusionId: "fusion-1",
    phaseId,
    model: "model",
    role: "primary",
    phaseKind: "primary",
    conversationScope: "root",
    durationMs: 2000,
    status: "succeeded",
    content: "PRIVATE",
    verdict: null,
    usage: { inputTokens: 10, outputTokens: 5, cachedTokens: 0, requestCount: 1, totalNanoAiu: 0 },
  },
});

function promiseGate() {
  let resolve!: () => void;
  const promise = new Promise<void>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}

const setup = Effect.fnUntraced(function* (
  fake: Fake,
  initialNativeThreadId?: string,
  initialSelection: ModelSelection = selection,
  runtimeSessionId = sessionId,
) {
  const adapter = yield* makeAdapter(
    { instanceId, settings, environment: { HOME: "/test-account" } },
    { clientFactory: () => fake.client },
  );
  const runtime = yield* adapter.openSession({
    threadId,
    providerSessionId: runtimeSessionId,
    modelSelection: initialSelection,
    runtimePolicy: policy,
    ...(initialNativeThreadId ? { initialNativeThreadId } : {}),
  });
  const emitted: ProviderAdapter.ProviderAdapterV2Event[] = [];
  const eventQueue = yield* Queue.unbounded<ProviderAdapter.ProviderAdapterV2Event>();
  yield* runtime.events.pipe(
    Stream.runForEach((event) =>
      Effect.sync(() => {
        emitted.push(event);
      }).pipe(Effect.andThen(Queue.offer(eventQueue, event))),
    ),
    Effect.forkScoped,
  );
  const takeEvent = Effect.fnUntraced(function* (
    predicate: (event: ProviderAdapter.ProviderAdapterV2Event) => boolean,
  ) {
    while (true) {
      const event = yield* Queue.take(eventQueue);
      if (predicate(event)) return event;
    }
  });
  const thread = yield* runtime.ensureThread({
    threadId,
    modelSelection: initialSelection,
    runtimePolicy: policy,
  });
  const start = Effect.fnUntraced(function* (ordinal = 1, turnSelection = initialSelection) {
    const now = yield* DateTime.now;
    const appThread: OrchestrationV2AppThread = {
      id: threadId,
      projectId: ProjectId.make("project"),
      title: "Test",
      providerInstanceId: instanceId,
      modelSelection: turnSelection,
      runtimeMode: policy.runtimeMode,
      interactionMode: "default",
      branch: null,
      worktreePath: null,
      activeProviderThreadId: thread.id,
      lineage: { parentThreadId: null, relationshipToParent: null, rootThreadId: threadId },
      forkedFrom: null,
      createdBy: "user",
      creationSource: "web",
      createdAt: now,
      updatedAt: now,
      archivedAt: null,
      settledOverride: null,
      settledAt: null,
      lastVisitedAt: null,
      deletedAt: null,
    };
    yield* runtime.startTurn({
      appThread,
      threadId,
      runId: RunId.make(`run-${ordinal}`),
      runOrdinal: ordinal,
      providerTurnOrdinal: ordinal,
      attemptId: RunAttemptId.make(`attempt-${ordinal}`),
      rootNodeId: NodeId.make(`root-${ordinal}`),
      providerThread: thread,
      message: {
        messageId: MessageId.make(`user-${ordinal}`),
        text: "Hello",
        attachments: [],
        createdBy: "user",
        creationSource: "web",
      },
      modelSelection: turnSelection,
      runtimePolicy: policy,
    });
  });
  const drain = () => runtime.readThreadSnapshot({ providerThread: thread });
  return { runtime, thread, emitted, start, drain, takeEvent };
});

const provide = <A, E, R>(effect: Effect.Effect<A, E, R>) =>
  effect.pipe(
    Effect.provideService(ProviderHost.ProviderHost, host),
    Effect.provide(McpProviderSessions.layer),
    Effect.scoped,
  );

describe("native Copilot V2", () => {
  it.effect(
    "preserves skill ownership, fresh inventory and errors across live session scopes",
    () =>
      provide(
        Effect.gen(function* () {
          const first = fakeSdk();
          const second = fakeSdk();
          for (const fake of [first, second])
            fake.setSkills({
              skills: [
                {
                  name: "review",
                  description: "Review changes",
                  source: "project",
                  userInvocable: true,
                  enabled: true,
                  path: "/workspace/.agents/skills/review/SKILL.md",
                },
              ],
            });
          let nextClient = 0;
          const inventories = new Map<string, ReadonlyArray<ServerProviderSkill>>();
          const adapter = yield* makeAdapter(
            { instanceId, settings, environment: { HOME: "/test-account" } },
            {
              clientFactory: () => (nextClient++ === 0 ? first.client : second.client),
              onSkills: (cwd, discovered) => {
                if (discovered) inventories.set(cwd, discovered);
                else inventories.delete(cwd);
              },
            },
          );
          if (!adapter.setSkillEnabled)
            throw new Error("Copilot instance skill controls are missing");
          const setSkillEnabled = adapter.setSkillEnabled;
          const unavailable = yield* adapter
            .setSkillEnabled({ skillName: "review", enabled: false })
            .pipe(Effect.result);
          assert.equal(unavailable._tag, "Failure");
          if (unavailable._tag === "Failure")
            assert.equal(unavailable.failure.reason, "session_unavailable");

          const firstScope = yield* Effect.acquireRelease(Scope.make(), (scope) =>
            Scope.close(scope, Exit.succeed(undefined)),
          );
          const open = Effect.fnUntraced(function* (id: string, scope: Scope.Scope, cwd: string) {
            const ownThread = ThreadId.make(id);
            const runtime = yield* adapter
              .openSession({
                threadId: ownThread,
                providerSessionId: ProviderSessionId.make(id),
                modelSelection: selection,
                runtimePolicy: { ...policy, cwd },
              })
              .pipe(Effect.provideService(Scope.Scope, scope));
            yield* runtime.ensureThread({
              threadId: ownThread,
              modelSelection: selection,
              runtimePolicy: { ...policy, cwd },
            });
          });
          yield* open("first-runtime", firstScope, "/workspace/first");
          yield* adapter.setSkillEnabled({ skillName: "review", enabled: false });
          assert.isFalse(first.skills[0]?.enabled);
          assert.deepEqual(inventories.get("/workspace/first"), []);
          yield* adapter.setSkillEnabled({ skillName: "review", enabled: true });
          assert.equal(inventories.get("/workspace/first")?.[0]?.name, "review");
          const readStarted = Promise.withResolvers<void>();
          const releaseRead = Promise.withResolvers<void>();
          first.setSkillsRead(async () => {
            const response = { skills: first.skills.map((skill) => ({ ...skill })) };
            readStarted.resolve();
            await releaseRead.promise;
            return response;
          });
          yield* Effect.gen(function* () {
            const disabling = yield* setSkillEnabled({ skillName: "review", enabled: false }).pipe(
              Effect.forkScoped,
            );
            yield* Effect.promise(() => readStarted.promise);
            const enabling = yield* setSkillEnabled({
              skillName: "review",
              enabled: true,
            }).pipe(Effect.forkScoped({ startImmediately: true }));
            assert.isFalse(first.skills[0]?.enabled);
            releaseRead.resolve();
            yield* Fiber.join(disabling);
            yield* Fiber.join(enabling);
            assert.isTrue(first.skills[0]?.enabled);
            assert.equal(inventories.get("/workspace/first")?.[0]?.name, "review");
          }).pipe(Effect.ensuring(Effect.sync(() => releaseRead.resolve())));
          first.setSkillsRead(undefined);

          const secondScope = yield* Effect.acquireRelease(Scope.make(), (scope) =>
            Scope.close(scope, Exit.succeed(undefined)),
          );
          yield* open("second-runtime", secondScope, "/workspace/second");
          const ambiguous = yield* adapter
            .setSkillEnabled({ skillName: "review", enabled: false })
            .pipe(Effect.result);
          assert.equal(ambiguous._tag, "Failure");
          if (ambiguous._tag === "Failure")
            assert.equal(ambiguous.failure.reason, "session_required");
          assert.isTrue(first.skills[0]?.enabled);
          assert.isTrue(second.skills[0]?.enabled);

          yield* adapter.setSkillEnabled({
            skillName: "review",
            enabled: false,
            providerSessionId: ProviderSessionId.make("second-runtime"),
          });
          assert.isTrue(first.skills[0]?.enabled);
          assert.isFalse(second.skills[0]?.enabled);
          assert.deepEqual(inventories.get("/workspace/second"), []);

          first.setSkillFailure(new Error("Native skill update rejected"));
          const failed = yield* adapter
            .setSkillEnabled({
              skillName: "review",
              enabled: false,
              providerSessionId: ProviderSessionId.make("first-runtime"),
            })
            .pipe(Effect.result);
          assert.equal(failed._tag, "Failure");
          if (failed._tag === "Failure") {
            assert.equal(failed.failure.reason, "operation_failed");
            assert.isDefined(failed.failure.cause);
          }
          assert.isTrue(first.skills[0]?.enabled);
          assert.equal(inventories.get("/workspace/first")?.[0]?.name, "review");
          yield* Scope.close(firstScope, Exit.succeed(undefined));
          yield* adapter.setSkillEnabled({ skillName: "review", enabled: true });
          assert.isTrue(second.skills[0]?.enabled);
          yield* Scope.close(secondScope, Exit.succeed(undefined));
          const closed = yield* adapter
            .setSkillEnabled({ skillName: "review", enabled: false })
            .pipe(Effect.result);
          assert.equal(closed._tag, "Failure");
          if (closed._tag === "Failure") assert.equal(closed.failure.reason, "session_unavailable");
        }),
      ),
  );

  it.effect.each([undefined, "native-copilot"])(
    "starts and settles with unsupported extensions disabled, native resume %s",
    (nativeId) =>
      provide(
        Effect.gen(function* () {
          const fake = fakeSdk({ persistedExtensions: true });
          const { start, drain, thread } = yield* setup(fake, nativeId);
          assert.equal(thread.nativeThreadRef?.nativeId, "native-copilot");
          assert.isTrue(fake.config.enableSkills);
          assert.equal(fake.config.enableConfigDiscovery, settings.enableConfigDiscovery);
          yield* start();
          fake.emit("assistant.message", { messageId: "reply", content: "Fixture completed" });
          fake.emit("session.idle");
          const snapshot = yield* drain();
          assert.equal(snapshot.providerTurns[0]?.status, "completed");
          assert.equal(snapshot.messages[0]?.text, "Fixture completed");
          assert.equal(fake.sent.length, 1);
        }),
      ),
  );
  it.effect("renews routing preferences without replacing ordinary model switches", () =>
    provide(
      Effect.gen(function* () {
        const adapter = yield* makeAdapter({ instanceId, settings, environment: {} });
        const auto: ModelSelection = { instanceId, model: "auto" };
        const high: ModelSelection = {
          ...auto,
          options: [{ id: "autoTier", value: "hydrafusion" }],
        };
        const max: ModelSelection = {
          ...auto,
          options: [{ id: "autoTier", value: "hydrafusion-max" }],
        };
        for (const [current, target, type] of [
          [selection, max, "restart_session"],
          [auto, max, "restart_session"],
          [high, max, "restart_session"],
          [max, max, "apply_on_next_turn"],
          [max, selection, "apply_on_next_turn"],
          [selection, auto, "apply_on_next_turn"],
        ] as const) {
          assert.deepEqual(
            yield* adapter.planSelectionTransition({
              current,
              target,
              sessionCapabilities: yield* adapter.getCapabilities(),
            }),
            { type },
          );
        }
      }),
    ),
  );
  it.effect.each(["single", "cascade", "critique"])(
    "publishes only committed root %s output before late plan telemetry",
    (pattern) =>
      provide(
        Effect.gen(function* () {
          const fake = fakeSdk();
          const autoSelection: ModelSelection = {
            instanceId,
            model: "auto",
            options: [{ id: "autoTier", value: "opaque-high" }],
          };
          fake.setCatalog({
            models: [],
            auto: {
              defaultTier: "opaque-high",
              tiers: [
                {
                  id: "opaque-high",
                  displayName: "High",
                  description: "",
                  type: "fusion",
                  status: { enabled: true },
                },
              ],
            },
          });
          const { start, drain, emitted, takeEvent } = yield* setup(fake, undefined, autoSelection);
          yield* start();
          const fusion = {
            fusionId: "fusion-1",
            phaseId: "solver",
            sourceModel: "solver-model",
            pattern,
            role: "solver",
            conversationScope: "root",
          };
          fake.emit("assistant.message_delta", {
            messageId: "answer",
            deltaContent: "DISCARDED DRAFT",
          });
          fake.emit("assistant.reasoning_delta", {
            reasoningId: "reason",
            deltaContent: "PRIVATE",
          });
          fake.emit("assistant.reasoning", { reasoningId: "reason", content: "PRIVATE" });
          fake.emit("assistant.message", {
            messageId: "answer",
            content: "DISCARDED DRAFT",
            fusion,
          });
          assert.equal((yield* drain()).messages.length, 0);
          assert.isFalse(emitted.some((event) => event.type === "message.updated"));
          fake.emit("assistant.message", {
            messageId: "review",
            content: "PRIVATE REVIEW",
            fusion: { ...fusion, commitId: "review-commit", conversationScope: "review" },
          });
          fake.emit("assistant.message", {
            messageId: "answer",
            content: "Correct final answer",
            originatingMessageId: "native-user-message-1",
            fusion: { ...fusion, commitId: "final-commit" },
          });
          fake.emit("session.fusion_resolved", {
            fusionId: "fusion-1",
            turnId: "different-native-namespace",
            primaryModel: "solver-model",
            fallbackModel: "fallback-model",
            contractVersion: 1,
            syntheticModel: "opaque-high",
            policy: "standard",
            pattern,
          });
          fake.emit("assistant.message", {
            messageId: "answer",
            content: "Correct final answer",
            fusion: { ...fusion, commitId: "final-commit" },
          });
          const route = yield* takeEvent(
            (event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "system_notice" &&
              event.turnItem.modelExecution?.fusionId === "fusion-1" &&
              event.turnItem.runId === RunId.make("run-1"),
          );
          const snapshot = yield* drain();
          assert.deepEqual(
            snapshot.messages.map((message) => message.text),
            ["Correct final answer"],
          );
          assert.isFalse(snapshot.messages[0]!.streaming);
          assert.ok(route.type === "turn_item.updated");
          if (route.type === "turn_item.updated")
            assert.equal(route.turnItem.runId, RunId.make("run-1"));
          assert.isFalse(
            emitted.some(
              (event) => event.type === "turn_item.updated" && event.turnItem.type === "reasoning",
            ),
          );
        }),
      ),
  );

  it.effect(
    "backfills Fusion ownership when its root message precedes the native send acknowledgement",
    () =>
      provide(
        Effect.gen(function* () {
          const fake = fakeSdk();
          const gate = promiseGate();
          fake.session.send = async () => {
            fake.emit("assistant.message", {
              messageId: "answer",
              originatingMessageId: "late-ack",
              content: "Correct final answer",
              fusion: {
                fusionId: "fusion-1",
                phaseId: "solver",
                conversationScope: "root",
                commitId: "commit",
              },
            });
            fake.emit("session.fusion_resolved", {
              fusionId: "fusion-1",
              turnId: "synthetic-turn",
              primaryModel: "solver-model",
              fallbackModel: "fallback-model",
              contractVersion: 1,
              syntheticModel: "opaque-high",
              policy: "standard",
              pattern: "single",
            });
            await gate.promise;
            return "late-ack";
          };
          const { start, drain, takeEvent } = yield* setup(fake);
          const running = yield* Effect.forkChild(start());
          yield* takeEvent(
            (event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "system_notice" &&
              event.turnItem.modelExecution?.fusionId === "fusion-1" &&
              event.turnItem.runId === null,
          );
          assert.equal((yield* drain()).messages.length, 0);
          gate.resolve();
          yield* Fiber.join(running);
          const route = yield* takeEvent(
            (event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "system_notice" &&
              event.turnItem.modelExecution?.fusionId === "fusion-1" &&
              event.turnItem.runId === RunId.make("run-1"),
          );
          const snapshot = yield* drain();
          assert.equal(snapshot.messages[0]?.text, "Correct final answer");
          assert.equal(snapshot.messages[0]?.runId, RunId.make("run-1"));
          assert.ok(route.type === "turn_item.updated");
          if (route.type === "turn_item.updated")
            assert.equal(route.turnItem.runId, RunId.make("run-1"));
        }),
      ),
  );

  it.effect(
    "keeps late committed answers on their original run without guessing unknown origins",
    () =>
      provide(
        Effect.gen(function* () {
          const fake = fakeSdk();
          const { start, drain } = yield* setup(fake);
          const answer = {
            messageId: "answer",
